def _seg_wrap(cls):
    """GitHubPRs that notes which requests each top-level method made (the model of Go's own list is made per method)."""
    class Rec(cls):
        def __init__(self, *a, world=None, **kw):
            super().__init__(*a, **kw)
            self.world, self.segs = world, []

        def _seg(self, name, args, fn):
            start = len(self.world.seen)
            try:
                res = fn()
                err = None
            except BaseException as e:  # noqa: BLE001
                res, err = None, e
            self.segs.append({"m": name, "args": args, "start": start, "end": len(self.world.seen), "res": res, "err": err})
            if err is not None:
                raise err
            return res

        def find_pr(self, repo, branch, *, tenants=False):
            return self._seg("find_pr", {"repo": repo, "branch": branch, "tenants": tenants}, lambda: super(Rec, self).find_pr(repo, branch, tenants=tenants))

        def pr_paths(self, repo, number, *, tenants=False):
            return self._seg("pr_paths", {"repo": repo, "n": number, "tenants": tenants}, lambda: super(Rec, self).pr_paths(repo, number, tenants=tenants))

        def repo_ready(self, repo, base="main", *, tenants=False):
            return self._seg("repo_ready", {"repo": repo, "tenants": tenants}, lambda: super(Rec, self).repo_ready(repo, base, tenants=tenants))

        def onboarding_prs(self, repo, *, tenants=False):
            return self._seg("onboarding_prs", {"repo": repo, "tenants": tenants}, lambda: super(Rec, self).onboarding_prs(repo, tenants=tenants))

        def read_file(self, repo, path, ref="main", *, tenants=False):
            return self._seg("read_file", {"repo": repo, "path": path, "tenants": tenants}, lambda: super(Rec, self).read_file(repo, path, ref, tenants=tenants))

        def ensure_pr(self, repo, branch, title, files, base="main", meta=None, body=None, *, tenants=False):
            return self._seg("ensure_pr", {"repo": repo, "branch": branch, "files": files, "tenants": tenants},
                             lambda: super(Rec, self).ensure_pr(repo, branch, title, files, base, meta=meta, body=body, tenants=tenants))

        def commit_xr(self, *a, **kw):
            return self._seg("commit_xr", {}, lambda: super(Rec, self).commit_xr(*a, **kw))
    return Rec


RecPRs = _seg_wrap(GitHubPRs)

