def broker_req(repo, tenants=False):
    owner, name = repo.split("/")
    body = {"owner": owner, "repo": name}
    if not tenants:
        app = name
        for pre in ("gitops-infra-", "gitops-"):
            if name.startswith(pre):
                app = name[len(pre):]
                break
        body["app"] = app
    return {"method": "POST", "target": "/b/agent-installation-token", "headers": {"authorization": "Bearer " + W.AGENT_TOKEN,
            "content-type": "application/json"}, "body": body}


def rename(v, names):
    """Python's branch names as Go's (a part of the session added), anywhere in a request, result or refusal."""
    s = json.dumps(v)
    for old, new in names.items():
        s = s.replace(old.replace("/", "%2F"), new.replace("/", "%2F")).replace(old, new)
    return json.loads(s)


def go_seg(seg, py, branch_names, files_of=None):
    """What Go sends for the requests `py` Python sent in one method."""
    m, a, res = seg["m"], seg["args"], seg["res"]
    repo = a.get("repo", T_REPO).lower() if "repo" in a else T_REPO
    if m in ("pr_paths", "onboarding_prs"):
        return [rename(r, branch_names) for r in py]
    if m == "find_pr":
        out = [rename(r, branch_names) for r in py]
        if res and res.get("state") != "merged":
            out.append(GET(f"/repos/{repo}/git/commits/{res['commit']}"))
        return out
    if m == "repo_ready":
        if len(py) == 1:
            return py
        return [py[0], GET(f"/repos/{repo}"), py[1]]
    if m in ("read_file", "ensure_pr") and len(py) == 1:
        return py    # the broker refused: nothing more is asked
    if m == "read_file":
        return [py[0], GET(f"/repos/{repo}"), *py[1:]]
    if m == "ensure_pr":
        files = a["files"]
        out = [py[0], GET(f"/repos/{repo}")]
        for r in py[1:]:
            if r["method"] == "POST" and r["target"].endswith("/git/trees"):
                out += W.base_reads(repo, files)
            out.append(rename(r, branch_names))
        if res and res.get("resumed") is True and not any(r["method"] == "POST" for r in py):
            out.append(GET(f"/repos/{repo}/git/commits/{res['commit']}"))
            for f in files:
                out.append(GET(f"/repos/{repo}/contents/{f['path']}?ref={res['commit']}"))
        return out
    raise AssertionError(m)


def go_requests_for(git, py_all, branch_names):
    out, i = [], 0
    for seg in sorted(git.segs, key=lambda s: s["start"]):
        out += [rename(r, branch_names) for r in py_all[i:seg["start"]]]
        if seg["m"] == "commit_xr":
            raise AssertionError("commit_xr is modelled by go_xr")
        out += go_seg(seg, py_all[seg["start"]:seg["end"]], branch_names)
        i = seg["end"]
    out += [rename(r, branch_names) for r in py_all[i:]]
    return out


def go_xr(py, app, path, name, branch_py, branch_go, repo=T_REPO):
    """What Go sends for the requests Python sent for one xr.request: the same tokens and checks, the default branch first, then (when
    it goes on to open the pull request) the list of the branch's pull requests, the branch itself, and the base's contents."""
    out = [py[0]]
    if len(py) == 1:
        return out
    out.append(GET(f"/repos/{repo}"))
    for r in py[1:]:
        if r["method"] == "GET" and r["target"].endswith(f"/contents/tenants/{app}?ref=main"):
            # Go reads the one listing of tenants/: the app is a directory of it, and every global name is decided against its siblings
            out.append(GET(f"/repos/{repo}/contents/tenants?ref=main"))
            continue
        if r["method"] == "GET" and r["target"].endswith("/git/ref/heads/main") and not any(x["target"].endswith("/git/ref/heads/" + branch_go.replace("/", "%2F")) for x in out):
            out.append(GET(f"/repos/{repo}/pulls?state=open&per_page=100"))
            out.append(GET(f"/repos/{repo}/pulls?head=o%3A{branch_go.replace('/', '%2F')}&state=all&per_page=5"))
            out.append(GET(f"/repos/{repo}/git/ref/heads/{branch_go}"))
        if r["method"] == "POST" and r["target"].endswith("/git/trees"):
            out += W.base_reads(repo, [{"path": path}])
        out.append(rename(r, {branch_py: branch_go}))
    return out


