def repo_routes(repo, pr_number=7, **over):
    r = W.gh_routes(repo, **{f"POST /repos/{repo}/pulls": jsr(201, {"number": pr_number, "html_url": f"https://github.com/{repo}/pull/{pr_number}"})})
    for k in [k for k in r if k.startswith("GET /repos/" + repo + "/contents/")]:
        del r[k]
    r.update(over)
    return r


def merge_routes(*parts):
    out = {}
    for p in parts:
        for k, v in p.items():
            out[k] = v
    return out


def pr_item(repo, number, branch, sha, state="open", merged=False):
    return {"number": number, "html_url": f"https://github.com/{repo}/pull/{number}", "state": state,
            "merged_at": "2026-11-10T00:00:00Z" if merged else None, "head": {"ref": branch, "sha": sha}}


def pulls_route(repo, branch, items):
    return {f"GET /repos/{repo}/pulls?head=o%3A{branch.replace('/', '%2F')}&state=all&per_page=5": jsr(200, items)}


def onboarding_route(repo, items=()):
    return {f"GET /repos/{repo}/pulls?head=o%3Aonboarding-resync&state=open&per_page=10": jsr(200, list(items))}


def commit_route(repo, sha, subject, meta):
    trailer = "".join(f"\nHangar-{k.title()}: {v}" for k, v in sorted(meta.items()))
    return {f"GET /repos/{repo}/git/commits/{sha}": jsr(200, {"tree": {"sha": TREE1}, "message": f"{subject}\n{trailer}"})}


