def _git(world):
    return RecPRs(W.TMP / "agent", broker_url="http://gh.test/b", api="https://api.github.test", opener=lambda req, t: world(req, t),
                  registry=REG, contract=CONTRACT, world=world)


def record(name, tool, args, routes, *, sess=SESSION, kind=None, branch_names=None, go=None, why=None, xr=None, py_args=None, **extra):
    world = W.World(routes or {})
    git = _git(world)
    gp = GlidepathAPI("http://gp.test/gp", W.TMP / "gp", opener=world, stream_opener=world.stream)
    b = Backends(git, None, None, None, None, None, gp, fake_airframe(registry=REG))
    h = hangar_handlers(b)
    out = W._outcome(lambda: h[tool](sess, py_args or args))
    if "result" in out and tool in TOOL_REGISTRY:
        out["effect"] = dispatch._effect(TOOL_REGISTRY[tool], args, out["result"])
    case = {"name": name, "tool": tool, "args": args, "session": sess.as_dict(), "routes": routes, "default": world.default, "obo": False,
            "git": True, "glidepath": True, "clock": False, "requests": world.seen, **W._norm(out), **extra}
    if py_args:
        case["py_args"] = py_args   # what Python was given: the same request, where Go writes a part of it itself (a matcher, protect)
    names = branch_names or {}
    if xr:
        py = world.seen
        gr = go_xr(py, xr["app"], xr["path"], xr["name"], xr["branch_py"], xr["branch_go"]) if py else []
        names = {xr["branch_py"]: xr["branch_go"]}
    else:
        gr = go_requests_for(git, world.seen, names)
    if go is not None:
        case["go"], case["why"] = go, why
    else:
        gv = {k: rename(case[k], names) for k in ("result", "denied", "error", "effect") if k in case}
        if gr != world.seen or any(gv[k] != case[k] for k in gv):
            case["go"] = {**gv, "requests": gr}
            case["why"] = why or ("Go works on a branch named with a part of the session, reads the repository's default branch, checks that a branch it "
                                  "resumes is its own session's and reads the base before it writes")
    CASES.append(case)
    return case, git


def direct(name, method, args, routes, *, go=None, why=None, **extra):
    """A GitHubPRs method that airframe.apply calls, driven alone."""
    world = W.World(routes)
    git = _git(world)
    a = dict(args)
    out = W._outcome(lambda: getattr(git, method)(**a))
    case = {"name": name, "tool": "direct:" + method, "args": args, "session": SESSION.as_dict(), "routes": routes, "default": world.default, "obo": False,
            "git": True, "glidepath": False, "clock": False, "requests": world.seen, **W._norm(out), **extra}
    seg = {"m": method, "args": {"repo": args.get("repo", T_REPO), **{k: v for k, v in args.items() if k in ("files", "tenants", "path")}},
           "res": out.get("result"), "start": 0, "end": len(world.seen)}
    if method in ("pr_paths", "onboarding_prs", "find_pr", "repo_ready", "read_file", "ensure_pr") and world.seen:
        seg["args"]["repo"] = args["repo"]
        gr = go_seg(seg, world.seen, {})
        if gr != world.seen:
            case["go_requests"] = gr
    if go:
        case["go"], case["why"] = go, why
    CASES.append(case)


